/* ===================== BÀI 24 · Reentrancy và chương trình con lồng ===================== */
/* Bài 24 · Reentrancy và chương trình con lồng (AMTS-EMB-002-M06-L04, X86-024) — sinh bởi tools/author/mpu8086/l24.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P24=[{"label": "Ví dụ: ba tầng gọi lồng nhau", "code": "; Ví dụ 1: ba tầng gọi lồng nhau\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        CALL    A1                      ; MAIN → A1 → B1 → C1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ninkt    PROC    NEAR                    ; in DL; hỏng AH\n        MOV     AH, 02H\n        INT     21H\n        RET\ninkt    ENDP\nA1      PROC    NEAR\n        MOV     DL, 'A'                 ; chữ hoa: vừa vào\n        CALL    inkt\n        CALL    B1\n        MOV     DL, 'a'                 ; chữ thường: sắp ra\n        CALL    inkt\n        RET\nA1      ENDP\nB1      PROC    NEAR\n        MOV     DL, 'B'\n        CALL    inkt\n        CALL    C1\n        MOV     DL, 'b'\n        CALL    inkt\n        RET\nB1      ENDP\nC1      PROC    NEAR\n        MOV     DL, 'C'\n        CALL    inkt                    ; sâu nhất: 4 địa chỉ trả về\n        MOV     DL, 'c'\n        CALL    inkt\n        RET\nC1      ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước và nhìn phần Ngăn xếp: mỗi CALL thêm một địa chỉ trả về lên trên. Lúc C1 gọi inkt có 4 word (0003h, 0015h, 0023h, 002Eh), SP = 00F8h. RET lấy word trên cùng nên thứ tự ra ngược thứ tự vào: màn hình in ABCcba. Đoán trước: khi đang ở trong C1 (trước CALL inkt), SP bằng bao nhiêu? Đáp án 00FAh."}, {"label": "Ví dụ: giai thừa đệ quy", "code": "; Ví dụ 2: giai thừa đệ quy, mỗi tầng cất CX\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 5\n        CALL    gt                      ; AX = 5!\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; gt: vào CX = n (0..8); ra AX = n!; hỏng DX; giữ CX\ngt      PROC    NEAR\n        CMP     CX, 1\n        JA      dequy\n        MOV     AX, 1                   ; điểm dừng: 0! = 1! = 1\n        RET\ndequy:\n        PUSH    CX                      ; mỗi tầng một bản n riêng\n        DEC     CX\n        CALL    gt                      ; AX = (n - 1)!\n        POP     CX\n        MUL     CX                      ; AX = n × (n - 1)!\n        RET\ngt      ENDP\n        END     MAIN\n", "input": "", "note": "gt(5) đi xuống 4 tầng: mỗi tầng PUSH CX (5, 4, 3, 2) và một địa chỉ trả về 0021h. Ở gt(1) điểm dừng trả AX = 1; trên đường về mỗi tầng POP CX lấy đúng n của mình rồi MUL CX: 1 × 2 × 3 × 4 × 5 = 120 = 0078h. MUL r16 tính 118 chu kỳ (cận dưới của 118–133). Đoán trước: ở tầng sâu nhất (CX = 1), SP bằng bao nhiêu? Đáp án 00FEh."}, {"label": "Ví dụ: biến cục bộ trong thủ tục đệ quy", "code": "; Ví dụ 3: biến cục bộ [BP-2] trong thủ tục đệ quy\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmuoi    DW      10\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234\n        CALL    indec                   ; in 1234\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; indec: in AX (không dấu) hệ 10; hỏng AX, DX\nindec   PROC    NEAR\n        PUSH    BP\n        MOV     BP, SP\n        SUB     SP, 2                   ; [BP-2]: chữ số của tầng này\n        XOR     DX, DX\n        DIV     muoi                    ; AX = thương, DX = chữ số cuối\n        MOV     [BP-2], DX\n        OR      AX, AX\n        JZ      inra                    ; thương 0: hết chữ số phía trước\n        CALL    indec                   ; in các chữ số phía trước\ninra:\n        MOV     DX, [BP-2]\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        MOV     SP, BP                  ; bỏ biến cục bộ\n        POP     BP\n        RET\nindec   ENDP\n        END     MAIN\n", "input": "", "note": "Mỗi tầng indec dựng khung BP và dành [BP−2] cho chữ số của mình (SUB SP, 2). DIV muoi chia DX:AX cho 10: 1234 → thương 123, dư 4. Tầng trong in 1, 2, 3 trước; tầng ngoài in 4 sau cùng. Màn hình in 1234. MOV SP, BP bỏ biến cục bộ trước POP BP. Đoán trước: ở tầng ngoài cùng, [BP−2] bằng bao nhiêu? Đáp án 0004h."}, {"label": "Lỗi: đệ quy dùng biến toàn cục", "code": "; Ví dụ 4 (lỗi): đệ quy dùng biến toàn cục\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmuoi    DW      10\nchuso   DW      ?                       ; SAI: chỉ có một bản cho mọi tầng\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 1234\n        CALL    indec\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nindec   PROC    NEAR\n        XOR     DX, DX\n        DIV     muoi\n        MOV     chuso, DX               ; tầng sau ghi đè tầng trước\n        OR      AX, AX\n        JZ      inra\n        CALL    indec\ninra:\n        MOV     DX, chuso\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        RET\nindec   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: cùng thuật toán nhưng chữ số giữ trong biến toàn cục chuso. Tầng trong cùng (số 1) ghi chuso = 1 sau cùng; khi các tầng lần lượt in, cả bốn đều đọc chuso = 1: màn hình in 1111. Sửa: dùng biến cục bộ như Ví dụ 3 hoặc PUSH DX / POP DX. Đoán trước: lúc tầng ngoài cùng in, chuso bằng bao nhiêu? Đáp án 1."}, {"label": "Lỗi: ngắt gọi lại thủ tục đang dở", "code": "; Ví dụ 5 (lỗi): \"ngắt\" gọi lại thủ tục đang chạy dở\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntam     DB      ?                       ; biến toàn cục của in2lan\nco      DB      0                       ; đã giả lập ngắt chưa\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX\n        MOV     ES, AX                  ; ES = 0000h: bảng vectơ ngắt\n        MOV     WORD PTR ES:[180H], OFFSET ngat\n        MOV     WORD PTR ES:[182H], CS  ; vectơ 60h = CS:ngat\n        MOV     AL, 'A'\n        CALL    in2lan                  ; mong đợi: AA\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nin2lan  PROC    NEAR                    ; in AL hai lần\n        MOV     tam, AL\n        MOV     DL, tam\n        MOV     AH, 02H\n        INT     21H\n        CMP     co, 0                   ; giả lập: ngắt đến đúng lúc\n        JNE     tiep                    ; này, chỉ một lần\n        MOV     co, 1\n        INT     60H\ntiep:\n        MOV     DL, tam                 ; tam đã bị ghi đè\n        MOV     AH, 02H\n        INT     21H\n        RET\nin2lan  ENDP\nngat    PROC    NEAR                    ; chương trình phục vụ ngắt\n        PUSH    AX\n        PUSH    DX\n        MOV     AL, 'B'\n        CALL    in2lan                  ; dùng lại in2lan\n        POP     DX\n        POP     AX\n        IRET\nngat    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: hai lệnh MOV WORD PTR ES:[180h]… ghi vectơ 60h = CS:ngat. in2lan ghi tam = 'A', in A, rồi INT 60h (giả lập ngắt, 51 chu kỳ) chạy ngat: ngat gọi in2lan('B') in BB và ghi tam = 'B'. IRET (24 chu kỳ) quay về giữa in2lan cũ, lúc này in tam = 'B'. Màn hình ABBB thay vì ABBA. Đoán trước: ngay sau IRET, tam bằng ký tự nào? Đáp án B."}, {"label": "Sửa: giữ ký tự trên ngăn xếp", "code": "; Ví dụ 6 (sửa): ký tự giữ trên ngăn xếp, không dùng tam\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DB      0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX\n        MOV     ES, AX\n        MOV     WORD PTR ES:[180H], OFFSET ngat\n        MOV     WORD PTR ES:[182H], CS\n        MOV     AL, 'A'\n        CALL    in2lan\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\nin2lan  PROC    NEAR                    ; in AL hai lần; reentrant\n        PUSH    AX                      ; mỗi lần gọi một bản riêng\n        MOV     DL, AL\n        MOV     AH, 02H\n        INT     21H\n        CMP     co, 0\n        JNE     tiep\n        MOV     co, 1\n        INT     60H\ntiep:\n        POP     DX                      ; DL = ký tự của chính lần gọi này\n        MOV     AH, 02H\n        INT     21H\n        RET\nin2lan  ENDP\nngat    PROC    NEAR\n        PUSH    AX\n        PUSH    DX\n        MOV     AL, 'B'\n        CALL    in2lan\n        POP     DX\n        POP     AX\n        IRET\nngat    ENDP\n        END     MAIN\n", "input": "", "note": "Bản sửa của Ví dụ 5: in2lan PUSH AX ngay đầu, nên mỗi lần gọi có bản ký tự riêng trên ngăn xếp; lần gọi từ ngat cất 'B' ở chỗ khác. Sau IRET, POP DX lấy lại 'A' của chính lần gọi đầu: màn hình ABBA. Xem phần Ngăn xếp lúc đang ở trong ngat: FLAGS, CS, IP do INT 60h cất nằm giữa hai bản ký tự. Đoán trước: ký tự cuối cùng được in là gì? Đáp án A."}, {"label": "Lỗi: đệ quy không có điểm dừng", "code": "; Ví dụ 7 (lỗi): đệ quy không có điểm dừng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ncanh    DW      1234H                   ; nằm dưới vùng ngăn xếp\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        XOR     AX, AX\n        CALL    dequy\n        MOV     AX, 4C00H               ; không bao giờ tới đây\n        INT     21H\nMAIN    ENDP\ndequy   PROC    NEAR\n        PUSH    AX                      ; 2 byte mỗi tầng\n        INC     AX\n        CALL    dequy                   ; thêm 2 byte: không có điểm dừng\n        POP     AX\n        RET\ndequy   ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: dequy không có điểm dừng. Mỗi tầng PUSH AX và CALL thêm 4 byte; SP giảm mãi, qua 0000h thì quay về FFFEh và ghi đè toàn bộ đoạn SS, kể cả biến canh ở SS:0000. Trình mô phỏng dừng ở giới hạn 2 000 000 lệnh (canh lúc đó là 0043h). Trên 8086 thật không có lỗi nào được báo. Sửa: thêm điểm dừng và giới hạn độ sâu. Đoán trước: sau 2 tầng (trước PUSH AX thứ ba), SP bằng bao nhiêu? Đáp án 0106h."}];
const sim24=makeX86Sim(document.getElementById("x86-l24"),{id:"s24",presets:P24,file:"BAI24.ASM"});
makeX86Ex(document.getElementById("ex-l24"),sim24,[{"t": "Giai thừa đệ quy", "d": "Đọc một phím chữ số n (0–8) bằng INT 21h hàm 08h, tính n! và ghi vào biến word kq (8! = 40320 vẫn vừa 16 bit). Viết thân thủ tục gt theo hợp đồng: vào CX = n; ra AX = n!; được làm hỏng DX; phải giữ CX. Dùng đệ quy: n! = n × (n − 1)!, điểm dừng 0! = 1! = 1. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: giai thừa bằng thủ tục đệ quy\n; Hợp đồng gt: vào CX = n (0..8); ra AX = n!;\n; hỏng DX; giữ CX. Code mẫu mới có điểm dừng.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; phím '0'..'8'\n        SUB     AL, '0'\n        MOV     AH, 0\n        MOV     CX, AX\n        CALL    gt\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\ngt      PROC    NEAR\n        MOV     AX, 1                   ; mới đúng với n = 0, 1\n        RET\ngt      ENDP\n        END     MAIN\n", "tests": [{"in": "5", "mem": [{"at": "kq", "word": 120}]}, {"in": "0", "mem": [{"at": "kq", "word": 1}]}, {"in": "1", "mem": [{"at": "kq", "word": 1}]}, {"in": "8", "mem": [{"at": "kq", "word": 40320}]}, {"in": "3", "mem": [{"at": "kq", "word": 6}]}, {"in": "7", "mem": [{"at": "kq", "word": 5040}]}]}, {"t": "Sửa thủ tục đệ quy dùng biến chung", "d": "MAIN đọc hai phím chữ số (hàng chục, hàng đơn vị) thành số 0–99 trong AX rồi gọi inbin để in số đó hệ 2, không có số 0 thừa ở đầu (số 0 in 0). inbin trong code mẫu dùng biến toàn cục bit nên mọi tầng đệ quy in cùng một bit. Sửa inbin cho đúng; không sửa MAIN. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: in số hệ 2 bằng thủ tục đệ quy\n; inbin chạy sai vì mọi tầng dùng chung biến bit.\n; Hãy sửa inbin cho đúng (không sửa MAIN).\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nbit     DB      ?                       ; biến toàn cục dùng chung\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; chữ số hàng chục\n        SUB     AL, '0'\n        MOV     BL, 10\n        MUL     BL                      ; AX = chục × 10\n        MOV     CX, AX\n        MOV     AH, 08H\n        INT     21H                     ; chữ số hàng đơn vị\n        SUB     AL, '0'\n        MOV     AH, 0\n        ADD     AX, CX                  ; AX = số 0..99\n        CALL    inbin\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; inbin: in AX hệ 2, không có số 0 thừa ở đầu. Hỏng AX, DX.\ninbin   PROC    NEAR\n        MOV     DX, AX\n        AND     DL, 1                   ; bit cuối\n        MOV     bit, DL                 ; tầng sau ghi đè tầng trước\n        SHR     AX, 1\n        JZ      inra                    ; không còn bit nào phía trước\n        CALL    inbin                   ; in các bit phía trước\ninra:\n        MOV     DL, bit\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        RET\ninbin   ENDP\n        END     MAIN\n", "tests": [{"in": "05", "out": "101"}, {"in": "00", "out": "0"}, {"in": "01", "out": "1"}, {"in": "10", "out": "1010"}, {"in": "99", "out": "1100011"}, {"in": "64", "out": "1000000"}, {"in": "37", "out": "100101"}]}, {"t": "Fibonacci không đệ quy", "d": "Đọc hai phím chữ số (hàng chục, hàng đơn vị) thành n = 0..20 và ghi số Fibonacci F(n) vào biến word kq (F(0) = 0, F(1) = 1, F(n) = F(n − 1) + F(n − 2); F(20) = 6765). Không in gì; kết thúc bằng INT 21h hàm 4Ch. Code mẫu đệ quy đúng nhưng số lời gọi tăng theo hàm mũ. Viết lại để đạt cả giới hạn chu kỳ và byte mã.", "start": "; Bài tập 3: số Fibonacci F(n), n = 0..20\n; Bản đệ quy này đúng nhưng mỗi lời gọi sinh hai lời\n; gọi nữa. Hãy viết lại cho đạt giới hạn chu kỳ, byte.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; chữ số hàng chục\n        SUB     AL, '0'\n        MOV     BL, 10\n        MUL     BL\n        MOV     CX, AX\n        MOV     AH, 08H\n        INT     21H                     ; chữ số hàng đơn vị\n        SUB     AL, '0'\n        MOV     AH, 0\n        ADD     CX, AX                  ; CX = n\n        CALL    fib\n        MOV     kq, AX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; fib: vào CX = n; ra AX = F(n); hỏng DX; giữ CX\nfib     PROC    NEAR\n        CMP     CX, 1\n        JA      dequy\n        MOV     AX, CX                  ; F(0) = 0, F(1) = 1\n        RET\ndequy:\n        PUSH    CX\n        DEC     CX\n        CALL    fib                     ; AX = F(n - 1)\n        PUSH    AX\n        DEC     CX\n        CALL    fib                     ; AX = F(n - 2)\n        POP     DX\n        ADD     AX, DX\n        POP     CX\n        RET\nfib     ENDP\n        END     MAIN\n", "tests": [{"in": "10", "mem": [{"at": "kq", "word": 55}]}, {"in": "00", "mem": [{"at": "kq", "word": 0}]}, {"in": "01", "mem": [{"at": "kq", "word": 1}]}, {"in": "02", "mem": [{"at": "kq", "word": 1}]}, {"in": "20", "mem": [{"at": "kq", "word": 6765}]}, {"in": "15", "mem": [{"at": "kq", "word": 610}]}], "perf": {"cycles": 800, "bytes": 50}}]);

makeQuiz("quiz24","score24",[{"q": "MAIN gọi A, A gọi B, B gọi C (đều là lời gọi gần, không tham số, không PUSH nào khác). Khi C đang chạy, có bao nhiêu byte địa chỉ trả về trên ngăn xếp, và RET của C về đâu?", "o": ["6 byte; RET của C về thẳng MAIN vì MAIN gọi trước", "2 byte; mỗi CALL mới thay địa chỉ trả về cũ", "6 byte; RET của C về lệnh sau CALL C trong B", "4 byte; địa chỉ trả về về MAIN không cần cất"], "a": 2, "e": "Ba lời gọi gần cất ba địa chỉ trả về (3 × 2 byte), chồng lên nhau. RET luôn lấy địa chỉ trên cùng, là địa chỉ trong B. CALL không ghi đè địa chỉ cũ mà PUSH thêm."}, {"q": "Thủ tục đệ quy sau in gì khi gọi với AX = 21 (10101b)?<pre class=\"mp-asm\">inbin   PROC    NEAR\n        MOV     DX, AX\n        AND     DL, 1\n        MOV     bit, DL                 ; bit DB ? (toàn cục)\n        SHR     AX, 1\n        JZ      inra\n        CALL    inbin\ninra:\n        MOV     DL, bit\n        ADD     DL, '0'\n        MOV     AH, 02H\n        INT     21H\n        RET\ninbin   ENDP<\/pre>", "o": ["10101", "10000", "11111", "1"], "a": 2, "e": "Mọi tầng ghi vào cùng biến bit; tầng sâu nhất (bit cao nhất = 1) ghi sau cùng, và cả 5 tầng đều in giá trị đó: 11111. Muốn in 10101, mỗi tầng phải giữ bit riêng trên ngăn xếp (bài tập 2)."}, {"q": "Mỗi tầng của một thủ tục đệ quy gần dùng khung: tham số 2 byte, địa chỉ trả về, BP cũ và 4 byte biến cục bộ. Độ sâu đệ quy tối đa 50. Ngăn xếp cần ít nhất bao nhiêu byte cho riêng các khung này?", "o": ["400 byte (50 × 8)", "500 byte (50 × 10)", "300 byte (50 × 6)", "200 byte (50 × 4, chỉ biến cục bộ)"], "a": 1, "e": "Mỗi khung: tham số 2 + địa chỉ trả về 2 + BP 2 + cục bộ 4 = 10 byte; 50 tầng sống cùng lúc → 500 byte. Còn phải cộng phần dự phòng cho ngắt và DOS. Bỏ sót địa chỉ trả về hoặc BP là nhầm phổ biến."}, {"q": "Chương trình chính đang chạy dở thủ tục <code>dem<\/code> (đọc biến toàn cục <code>n<\/code>, cộng 1, ghi lại) thì một ngắt đến, và chương trình phục vụ ngắt cũng gọi <code>dem<\/code>. Chương trình phục vụ ngắt đã PUSH/POP mọi thanh ghi nó dùng. Kết quả có thể sai không?", "o": ["Có: nếu ngắt đến sau lúc đọc n và trước lúc ghi, một lần cộng bị mất", "Không: cất đủ thanh ghi là đủ để thủ tục reentrant", "Không: CPU tự cấm ngắt trong lúc một thủ tục đang chạy", "Có, nhưng chỉ khi thủ tục là FAR vì CS bị đổi"], "a": 0, "e": "Chương trình chính đã đọc n vào thanh ghi; ngắt tăng n và ghi; chương trình chính ghi lại giá trị cũ + 1, mất lần tăng của ngắt. Cất thanh ghi không bảo vệ biến chung; CPU chỉ cấm ngắt khi IF = 0 (CLI), không tự cấm theo thủ tục."}, {"q": "Cần tính F(20) của dãy Fibonacci trên 8086. Cách nào hợp lý nhất?", "o": ["Đệ quy hai nhánh, vì độ sâu chỉ 20 tầng", "Vòng lặp giữ hai số liên tiếp trong thanh ghi", "Đệ quy hai nhánh, nhưng tăng .STACK lên 64 KB", "Đệ quy hai nhánh với biến toàn cục để bớt PUSH"], "a": 1, "e": "Độ sâu đệ quy chỉ 20 nhưng số lời gọi là 21 891: ngăn xếp không thiếu, thời gian mới là vấn đề. Tăng .STACK không bớt lời gọi; biến toàn cục còn làm đệ quy sai. Vòng lặp cần 20 lần cộng (bài tập 3)."}]);

